exercises.fix_solution:
from pydantic import BaseModel, ConfigDict, Field


class Cfg(BaseModel):
    """Run settings."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    min_base: int = Field(default=50, gt=0)


def with_min_base(cfg: Cfg, value: int) -> Cfg:
    """Return a validated copy of cfg with a new min_base."""
    return Cfg.model_validate({**cfg.model_dump(), "min_base": value})
